stylesheet:
QMainWindow { background-color: #f4f4f4; }
QTreeWidget { background-color: #ffffff; alternate-background-color: #ededed; color: #1c1c1c; border: 1px solid #cfcfcf; }
QTreeWidget::item:selected { background-color: #6c8cff; color: #ffffff; }
QGroupBox { border: 1px solid #cfcfcf; border-radius: 6px; margin-top: 10px; padding: 10px; }
QGroupBox::title { subcontrol-origin: margin; left: 10px; padding: 0 3px 0 3px; }
QTextEdit { background-color: #ffffff; color: #1c1c1c; border: 1px solid #cfcfcf; }
QPushButton { background-color: #e0e0e0; color: #1c1c1c; border-radius: 4px; padding: 4px 10px; }
QPushButton:hover { background-color: #d6d6d6; }
QPushButton:pressed { background-color: #c9c9c9; }
QLabel { color: #1c1c1c; }
QMenu { background-color: #ffffff; color: #1c1c1c; border: 1px solid #cfcfcf; }
QMenu::item { padding: 4px 20px 4px 24px; background-color: transparent; }
QMenu::item:selected { background-color: #6c8cff; color: #ffffff; }
QMenu::separator { height: 1px; background: #cfcfcf; margin-left: 4px; margin-right: 4px; }
